/* ═══════════════════════════════════════
   ? FIXED CUSTOM IMAGE
   Stays on screen while scrolling/clicking
   ═══════════════════════════════════════ */

body::after {
    content: "";
    position: fixed;

    /* Position on the screen */
    right: 20px;
    bottom: 20px;

    /* Image size */
    width: 200px;
    height: 200px;

    /* YOUR CUSTOM IMAGE */
    background-image: url("https://www.image2url.com/r2/default/images/1788583624890-e2c29bdd-9829-4235-85fb-cae4959402e6.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;

    /* Stay above the entire page */
    z-index: 999999 !important;

    /* Don't block clicks */
    pointer-events: none;
}
